#include "args.hpp"
#include <iostream>
#include <cstdlib>
#include <cstring>
#include <sstream>

static void write_brief(std::ostream& os, const std::string& program_name) {
    os << "Brief USAGE: \n"
       << "   " << program_name << "  [-i <path to directory>] [-s <positive integer>] [-d <a\n"
       << "                 string containing two space-seprated positive integers>]\n"
       << "                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]\n"
       << "                 [-h] <Array of strings> ...\n"
       << "\n"
       << "For complete USAGE and HELP type: \n"
       << "   " << program_name << " --help\n"
       << "\n";
}

void print_brief_usage(const std::string& program_name) {
    write_brief(std::cerr, program_name);
}

void print_help(const std::string& program_name) {
    std::cout <<
        "\n"
        "USAGE: \n"
        "\n"
        "   " << program_name << "  [-i <path to directory>] [-s <positive integer>] [-d <a\n"
        "                 string containing two space-seprated positive integers>]\n"
        "                 [-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version]\n"
        "                 [-h] <Array of strings> ...\n"
        "\n"
        "\n"
        "Where: \n"
        "\n"
        "   -i <path to directory>,  --replaydirectory <path to directory>\n"
        "     The path to directory for replay output.\n"
        "\n"
        "   -s <positive integer>,  --seed <positive integer>\n"
        "     The seed for the map generator.\n"
        "\n"
        "   -d <a string containing two space-seprated positive integers>, \n"
        "      --dimensions <a string containing two space-seprated positive\n"
        "      integers>\n"
        "     The dimensions of the map.\n"
        "\n"
        "   -n <{1,2,3,4,5,6}>,  --nplayers <{1,2,3,4,5,6}>\n"
        "     Create a map that will accommodate n players [SINGLE PLAYER MODE\n"
        "     ONLY].\n"
        "\n"
        "   -r,  --noreplay\n"
        "     Turns off the replay generation.\n"
        "\n"
        "   -t,  --timeout\n"
        "     Causes game environment to ignore timeouts (give all bots infinite\n"
        "     time).\n"
        "\n"
        "   -o,  --override\n"
        "     Overrides player-sent names using cmd args [SERVER ONLY].\n"
        "\n"
        "   -q,  --quiet\n"
        "     Runs game in quiet mode, producing machine-parsable output.\n"
        "\n"
        "   --,  --ignore_rest\n"
        "     Ignores the rest of the labeled arguments following this flag.\n"
        "\n"
        "   --version\n"
        "     Displays version information and exits.\n"
        "\n"
        "   -h,  --help\n"
        "     Displays usage information and exits.\n"
        "\n"
        "   <Array of strings>  (accepted multiple times)\n"
        "     Start commands for bots.\n"
        "\n"
        "\n"
        "   Halite Game Environment\n"
        "\n";
}

void print_version(const std::string& program_name) {
    std::cout << "\n" << program_name << "  version: 1.2\n\n";
}

// Parse a positive integer (unsigned wrap like strtoul). Returns true on success.
static bool parse_uint(const std::string& s, unsigned int& out) {
    if (s.empty()) return false;
    const char* p = s.c_str();
    char* end = nullptr;
    long long val = std::strtoll(p, &end, 10);
    if (end == p || *end != '\0') return false;
    out = (unsigned int)(long long)val;
    return true;
}

static bool parse_dims(const std::string& s, int& w, int& h) {
    // Must be exactly two space-separated positive integers
    std::istringstream iss(s);
    std::string a, b, c;
    if (!(iss >> a)) return false;
    if (!(iss >> b)) return false;
    if (iss >> c) return false;
    try {
        size_t pa, pb;
        int av = std::stoi(a, &pa);
        int bv = std::stoi(b, &pb);
        if (pa != a.size() || pb != b.size()) return false;
        if (av < 1 || bv < 1) return false;
        w = av;
        h = bv;
        return true;
    } catch (...) {
        return false;
    }
}

static void parse_error(const std::string& arg_label, const std::string& msg, const std::string& program_name) {
    std::cerr << "PARSE ERROR: Argument: " << arg_label << "\n"
              << "             " << msg << "\n"
              << "\n";
    write_brief(std::cerr, program_name);
    std::exit(1);
}

bool parse_args(int argc, char** argv, Args& out, const std::string& program_name) {
    bool ignore_rest = false;
    bool seed_set = false;
    bool dimensions_set = false;
    bool nplayers_set = false;
    bool replay_set = false;

    auto need_value = [&](int& i, const char* label_short, const char* label_long) -> std::string {
        if (i + 1 >= argc) {
            std::string label = std::string(label_short) + " (" + label_long + ")";
            parse_error(label, "Missing a value for this argument!", program_name);
        }
        return std::string(argv[++i]);
    };

    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (ignore_rest) {
            out.bot_commands.push_back(a);
            continue;
        }
        if (a == "--") { ignore_rest = true; continue; }
        if (a == "--ignore_rest") { ignore_rest = true; continue; }
        if (a == "-h" || a == "--help") {
            print_help(program_name);
            std::exit(0);
        }
        if (a == "--version") {
            print_version(program_name);
            std::exit(0);
        }
        if (a == "-r" || a == "--noreplay") { out.no_replay = true; continue; }
        if (a == "-t" || a == "--timeout") { out.no_timeout = true; continue; }
        if (a == "-o" || a == "--override") { out.override = true; continue; }
        if (a == "-q" || a == "--quiet") { out.quiet = true; continue; }

        if (a == "-i" || a == "--replaydirectory") {
            if (replay_set) parse_error("-i (--replaydirectory)", "Argument already set!", program_name);
            out.replay_dir = need_value(i, "-i", "--replaydirectory");
            replay_set = true;
            continue;
        }
        if (a == "-s" || a == "--seed") {
            if (seed_set) parse_error("-s (--seed)", "Argument already set!", program_name);
            std::string v = need_value(i, "-s", "--seed");
            unsigned int val;
            if (!parse_uint(v, val)) {
                parse_error("-s (--seed)", "Couldn't read argument value from string '" + v + "'", program_name);
            }
            out.has_seed = true;
            out.seed = val;
            seed_set = true;
            continue;
        }
        if (a == "-d" || a == "--dimensions") {
            if (dimensions_set) parse_error("-d (--dimensions)", "Argument already set!", program_name);
            std::string v = need_value(i, "-d", "--dimensions");
            int w, h;
            if (!parse_dims(v, w, h)) {
                parse_error("-d (--dimensions)", "Couldn't read argument value from string '" + v + "'", program_name);
            }
            out.has_dimensions = true;
            out.width = w;
            out.height = h;
            dimensions_set = true;
            continue;
        }
        if (a == "-n" || a == "--nplayers") {
            if (nplayers_set) parse_error("-n (--nplayers)", "Argument already set!", program_name);
            std::string v = need_value(i, "-n", "--nplayers");
            unsigned int val;
            if (!parse_uint(v, val)) {
                parse_error("-n (--nplayers)", "Couldn't read argument value from string '" + v + "'", program_name);
            }
            // TCLAP's ValuesConstraint - only values 1-6 are valid; but we still accept to parse, validate later
            out.has_nplayers = true;
            out.nplayers = (int)val;
            nplayers_set = true;
            continue;
        }

        // Fall-through: treated as positional bot command (unknown flags too)
        out.bot_commands.push_back(a);
    }

    return true;
}
