#include "bot.hpp"
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <cstdio>
#include <cstring>
#include <cerrno>
#include <chrono>

Bot::Bot(const std::string& cmd, int pid) : command_(cmd), player_id_(pid) {}
Bot::~Bot() { stop(); }

bool Bot::start() {
    int in_pipe[2], out_pipe[2];
    if (pipe(in_pipe) != 0) return false;
    if (pipe(out_pipe) != 0) { close(in_pipe[0]); close(in_pipe[1]); return false; }

    pid_t pid = fork();
    if (pid < 0) {
        close(in_pipe[0]); close(in_pipe[1]);
        close(out_pipe[0]); close(out_pipe[1]);
        return false;
    }
    if (pid == 0) {
        // Child
        dup2(in_pipe[0], STDIN_FILENO);
        dup2(out_pipe[1], STDOUT_FILENO);
        close(in_pipe[0]); close(in_pipe[1]);
        close(out_pipe[0]); close(out_pipe[1]);
        execl("/bin/sh", "sh", "-c", command_.c_str(), (char*)nullptr);
        _exit(127);
    }
    close(in_pipe[0]);
    close(out_pipe[1]);
    stdin_fd_ = in_pipe[1];
    stdout_fd_ = out_pipe[0];
    pid_ = pid;
    alive_ = true;

    // Set stdout to non-blocking for polling
    int flags = fcntl(stdout_fd_, F_GETFL, 0);
    fcntl(stdout_fd_, F_SETFL, flags | O_NONBLOCK);
    return true;
}

void Bot::stop() {
    if (stdin_fd_ >= 0) { close(stdin_fd_); stdin_fd_ = -1; }
    if (stdout_fd_ >= 0) { close(stdout_fd_); stdout_fd_ = -1; }
    if (pid_ > 0) {
        kill(pid_, SIGKILL);
        int status = 0;
        waitpid(pid_, &status, 0);
        pid_ = -1;
    }
    alive_ = false;
}

bool Bot::send_line(const std::string& line) {
    if (stdin_fd_ < 0) return false;
    std::string data = line + "\n";
    ssize_t total = 0;
    while (total < (ssize_t)data.size()) {
        ssize_t w = write(stdin_fd_, data.data() + total, data.size() - total);
        if (w < 0) {
            if (errno == EINTR) continue;
            return false;
        }
        total += w;
    }
    return true;
}

bool Bot::read_available(int timeout_ms, std::string& out) {
    if (stdout_fd_ < 0) return false;
    struct pollfd pfd;
    pfd.fd = stdout_fd_;
    pfd.events = POLLIN;
    int r = poll(&pfd, 1, timeout_ms);
    if (r <= 0) return false;
    if (!(pfd.revents & POLLIN)) {
        // POLLHUP etc.
        // try to read remaining
    }
    char buf[4096];
    ssize_t n = read(stdout_fd_, buf, sizeof(buf));
    if (n <= 0) return false;
    out.append(buf, buf + n);
    return true;
}

std::string Bot::read_line(int timeout_ms) {
    using clock = std::chrono::steady_clock;
    auto deadline = (timeout_ms < 0) ? clock::time_point::max()
                                     : clock::now() + std::chrono::milliseconds(timeout_ms);
    while (true) {
        auto pos = read_buffer_.find('\n');
        if (pos != std::string::npos) {
            std::string line = read_buffer_.substr(0, pos);
            read_buffer_.erase(0, pos + 1);
            return line;
        }
        int remaining = -1;
        if (timeout_ms >= 0) {
            auto now = clock::now();
            if (now >= deadline) break;
            remaining = (int)std::chrono::duration_cast<std::chrono::milliseconds>(deadline - now).count();
            if (remaining < 0) remaining = 0;
        }
        std::string chunk;
        if (!read_available(remaining, chunk)) {
            // EOF or timeout: return whatever is buffered if any, else empty
            break;
        }
        read_buffer_ += chunk;
    }
    if (!read_buffer_.empty()) {
        std::string s = read_buffer_;
        read_buffer_.clear();
        return s;
    }
    return "";
}
