        // try to read remaining
    }
    char buf[4096];
    ssize_t n = read(stdout_fd_, buf, sizeof(buf));
    if (n <= 0) return false;
    out.append(buf, buf + n);
    return true;
}

std::string Bot::read_line(int timeout_ms) {
    using clock = std::chrono::steady_clock;
    auto deadline = (timeout_ms < 0) ? clock::time_point::max()
                                     : clock::now() + std::chrono::milliseconds(timeout_ms);
    while (true) {
        auto pos = read_buffer_.find('\n');
        if (pos != std::string::npos) {
            std::string line = read_buffer_.substr(0, pos);
            read_buffer_.erase(0, pos + 1);
            return line;
        }
        int remaining = -1;
        if (timeout_ms >= 0) {
            auto now = clock::now();
            if (now >= deadline) break;
            remaining = (int)std::chrono::duration_cast<std::chrono::milliseconds>(deadline - now).count();
            if (remaining < 0) remaining = 0;
        }
        std::string chunk;
        if (!read_available(remaining, chunk)) {
            // EOF or timeout: return whatever is buffered if any, else empty
            break;
        }
        read_buffer_ += chunk;
    }
    if (!read_buffer_.empty()) {
        std::string s = read_buffer_;
        read_buffer_.clear();
        return s;
    }
    return "";
}
