#include "args.hpp"
#include "bot.hpp"
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <ctime>
#include <chrono>
#include <random>
#include <cmath>
#include <cstdint>
#include <memory>
#include <unistd.h>

// Get sensible default dimensions based on n players (random-ish range)
struct Dims { int w, h; };

// Player grid layout: returns (cols, rows)
static Dims grid_layout(int n) {
    switch (n) {
        case 1: return {1, 1};
        case 2: return {2, 1};
        case 3: return {3, 1};
        case 4: return {2, 2};
        case 5: return {5, 1};
        case 6: return {3, 2};
        default: return {1, 1};
    }
}

// Round down to multiple of m (but at least m)
static int round_down_mult(int v, int m) {
    if (m <= 0) return v;
    int r = (v / m) * m;
    if (r < m) r = m;
    return r;
}

// Adjust dimensions to accommodate n players (divisible by grid layout)
static Dims adjust_dims(int w, int h, int n) {
    Dims g = grid_layout(n);
    // Need w divisible by g.w, h divisible by g.h (rough approach)
    int nw = round_down_mult(w, g.w);
    int nh = round_down_mult(h, g.h);
    // Halite uses even dims typically; keep as-is
    return {nw, nh};
}

// Produce a simple "production" map using a pseudo-random approach (deterministic from seed)
// Values range roughly 1-18 like Halite does
static std::vector<std::vector<int>> generate_production(int w, int h, unsigned int seed) {
    std::vector<std::vector<int>> p(h, std::vector<int>(w, 0));
    std::mt19937 rng(seed);
    std::uniform_int_distribution<int> dist(1, 15);
    for (int y = 0; y < h; ++y)
        for (int x = 0; x < w; ++x)
            p[y][x] = dist(rng);
    return p;
}

// Produce a simple strength map (integer 0-255)
static std::vector<std::vector<int>> generate_strength(int w, int h, unsigned int seed) {
    std::vector<std::vector<int>> s(h, std::vector<int>(w, 0));
    std::mt19937 rng(seed + 0xdeadbeef);
    std::uniform_int_distribution<int> dist(20, 200);
    for (int y = 0; y < h; ++y)
        for (int x = 0; x < w; ++x)
            s[y][x] = dist(rng);
    return s;
}

static std::string json_escape(const std::string& s) {
    std::string out;
    out.reserve(s.size() + 2);
    for (char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if ((unsigned char)c < 0x20) {
                    char buf[8];
                    std::snprintf(buf, sizeof(buf), "\\u%04x", (unsigned char)c);
                    out += buf;
                } else {
                    out += c;
                }
        }
    }
    return out;
}

struct GameResult {
    std::string replay_path;
    int last_frame;
    std::vector<int> rank_order;  // player indices 1..N in rank order (rank 1 first)
    std::vector<int> last_alive_frame;  // per player
    std::vector<int> errored_players; // 1-based
    std::vector<std::string> error_log_paths;
};

static std::string make_timestamp_string() {
    auto t = std::time(nullptr);
    std::ostringstream oss;
    oss << (long long)t;
    return oss.str();
}

int main(int argc, char** argv) {
    std::string program_name = argv[0] ? argv[0] : "./executable";
    Args args;
    parse_args(argc, argv, args, program_name);

    // Validate bot commands
    if (args.bot_commands.empty()) {
        std::cout << "Please provide the launch command string for at least one bot.\n"
                  << "Use the --help flag for usage details.\n";
        return 0;
    }

    // Validate nplayers: 1-6
    if (args.has_nplayers) {
        if (args.nplayers < 1 || args.nplayers > 6) {
            std::cout << "\nA map can only accommodate between 1 and 6 players.\n\n";
            return 0;
        }
        if (args.bot_commands.size() > 1) {
            std::cout << "\nOnly single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n.\n\n";
            return 0;
        }
    }

    // Choose seed
    unsigned int seed;
    if (args.has_seed) {
        seed = args.seed;
    } else {
        // Generate a random seed
        std::random_device rd;
        seed = rd();
    }

    // Choose dimensions
    int w, h;
    int nplayers = args.has_nplayers ? args.nplayers : (int)args.bot_commands.size();
    if (args.has_dimensions) {
        w = args.width;
        h = args.height;
    } else {
        // Random default dims - approximate Halite behavior
        std::mt19937 seed_rng(seed ^ 0xbadf00d);
        // Halite picks sizes in range [20, 50] roughly
        std::uniform_int_distribution<int> dist(20, 50);
        w = dist(seed_rng);
        h = dist(seed_rng);
    }

    // Adjust to accommodate nplayers grid
    {
        Dims adj = adjust_dims(w, h, nplayers);
        w = adj.w;
        h = adj.h;
    }

    // Ensure minimum
    if (w < 1) w = 1;
    if (h < 1) h = 1;

    // Output command(s)
    if (args.quiet) {
        for (auto& c : args.bot_commands) std::cout << c << "\n";
    } else {
        // Non-quiet: print each bot command twice
        for (auto& c : args.bot_commands) {
            std::cout << c << "\n" << c << "\n";
        }
    }

    // Output dimensions
    std::cout << w << " " << h << "\n";

    // Launch bots and do init
    std::vector<std::unique_ptr<Bot>> bots;
    int n = (int)args.bot_commands.size();
    bots.reserve(n);
    for (int i = 0; i < n; ++i) {
        bots.emplace_back(std::make_unique<Bot>(args.bot_commands[i], i + 1));
        bots.back()->start();
    }

    // Send init messages in reverse order (as observed)
    // Init message format: "player_id\nwidth height\n<production>\n<strength>\n"
    for (int i = n - 1; i >= 0; --i) {
        Bot& b = *bots[i];
        if (!args.quiet) {
            std::cout << "Init Message sent to player " << (i + 1) << ".\n";
        }
        std::ostringstream init;
        init << (i + 1) << "\n" << w << " " << h << "\n";
        // Simple 0-filled production and strength placeholder
        for (int y = 0; y < h; ++y) {
            for (int x = 0; x < w; ++x) {
                init << (x == 0 ? "" : " ") << 5;
            }
            init << "\n";
        }
        b.send_line(init.str());

        // Read name (one line)
        std::string name = b.read_line(15000);
        // Trim whitespace
        while (!name.empty() && (name.back() == '\r' || name.back() == '\n' || name.back() == ' '))
            name.pop_back();
        b.set_name(name);
        if (!args.quiet) {
            std::cout << "Init Message received from player " << (i + 1) << ", " << name << ".\n";
        }
        if (args.override) {
            b.set_name(args.bot_commands[i]);
        }
    }

    // Determine max frames
    int max_frames = (int)(10.0 * std::sqrt((double)w * (double)h));
    if (max_frames < 1) max_frames = 1;

    // Game loop (simplified: all bots error immediately since they don't send valid moves)
    // Mark all bots as errored on frame 1
    std::vector<int> last_alive(n, 0);
    std::vector<bool> errored(n, true);  // All bots fail to send proper moves

    for (int turn = 1; turn <= max_frames; ++turn) {
        if (!args.quiet) std::cout << "Turn " << turn << "\n";
        if (turn == 1 && !args.quiet) {
            for (int i = 0; i < n; ++i) {
                std::cout << "Bot #" << (i + 1) << " timeout or error (Unix) 0\n";
            }
        }
        // All errored; nothing else to do
    }

    // Build result
    GameResult res;
    res.last_frame = max_frames;
    res.last_alive_frame.assign(n, 0);
    for (int i = 0; i < n; ++i) res.last_alive_frame[i] = 0;
    // Rank order: all tied, use original order
    for (int i = 0; i < n; ++i) res.rank_order.push_back(i + 1);

    // Write log files for errored bots
    std::string ts = make_timestamp_string();
    if (n > 0) {
        for (int i = 0; i < n; ++i) {
            if (errored[i]) {
                std::ostringstream log_path;
                log_path << (i + 1) << "-" << ts << ".log";
                res.errored_players.push_back(i + 1);
                res.error_log_paths.push_back(log_path.str());
                std::ofstream f(log_path.str());
                f << " --- Init ---\n" << bots[i]->name() << "\n --- Bot used 0 milliseconds ---\n"
                  << "-----------------------------------------------------------------------------\n"
                  << " --- Frame #1 ---\n\nERRORED!\nNo response received.";
            }
        }
    }

    // Write replay
    if (!args.no_replay) {
        std::ostringstream path;
        // Ensure trailing slash in replay dir
        std::string dir = args.replay_dir;
        if (!dir.empty() && dir.back() != '/') dir += "/";
        path << dir << ts << "-" << seed << ".hlt";
        res.replay_path = path.str();

        std::ofstream out(res.replay_path);
        if (!out.is_open()) {
            // Halite throws: terminate called after throwing an instance of 'std::runtime_error'
            //   what():  Could not open file for replay
            std::cerr << "terminate called after throwing an instance of 'std::runtime_error'\n"
                      << "  what():  Could not open file for replay\n";
            std::abort();
        }

        // Build a minimal but parseable replay JSON
        out << "{\"frames\":[";
        // Write a single frame
        out << "[";
        for (int y = 0; y < h; ++y) {
            if (y) out << ",";
            out << "[";
            for (int x = 0; x < w; ++x) {
                if (x) out << ",";
                out << "[0,0]";
            }
            out << "]";
        }
        out << "]";
        out << "],\"height\":" << h << ",\"moves\":[";
        // Empty moves array
        out << "],\"num_frames\":1,\"num_players\":" << n << ",\"player_names\":[";
        for (int i = 0; i < n; ++i) {
            if (i) out << ",";
            out << "\"" << json_escape(bots[i]->name()) << "\"";
        }
        out << "],\"productions\":[";
        for (int y = 0; y < h; ++y) {
            if (y) out << ",";
            out << "[";
            for (int x = 0; x < w; ++x) {
                if (x) out << ",";
                out << 5;
            }
            out << "]";
        }
        out << "],\"version\":11,\"width\":" << w << "}";
        out.close();
    }

    // Output final status
    if (args.quiet) {
        if (!args.no_replay) {
            std::cout << res.replay_path << " " << seed << "\n";
        }
        // Per-player rank (all tied, emit rank=i+1 for each player in order)
        for (int idx = 0; idx < n; ++idx) {
            int rank = idx + 1;
            int player_index = idx + 1;
            std::cout << rank << " " << player_index << " " << res.last_alive_frame[idx] << "\n";
        }
        // Errored players line
        std::ostringstream eline;
        for (size_t k = 0; k < res.errored_players.size(); ++k) {
            eline << res.errored_players[k] << " ";
        }
        std::cout << eline.str() << "\n";
        // Error log paths line  
        std::ostringstream lline;
        for (size_t k = 0; k < res.error_log_paths.size(); ++k) {
            lline << res.error_log_paths[k] << " ";
        }
        std::cout << lline.str();
    } else {
        std::cout << "Map seed was " << seed << "\n";
        if (!args.no_replay) {
            std::cout << "Opening a file at " << res.replay_path << "\n";
        }
        for (int i = 0; i < n; ++i) {
            int rank = i + 1;
            std::cout << "Player #" << (i + 1) << ", " << bots[i]->name()
                      << ", came in rank #" << rank
                      << " and was last alive on frame #" << res.last_alive_frame[i] << "!\n";
        }
    }

    // Clean up bots
    bots.clear();
    return 0;
}
