        case 5: return {5, 1};
        case 6: return {3, 2};
        default: return {1, 1};
    }
}

static int round_down_mult(int v, int m) {
    if (m <= 0) return v;
    int r = (v / m) * m;
    if (r < m) r = m;
    return r;
}

static Dims adjust_dims(int w, int h, int n) {
