static std::string json_escape(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if ((unsigned char)c < 0x20) {
                    char buf[8];
                    std::snprintf(buf, sizeof(buf), "\\u%04x", (unsigned char)c);
                    out += buf;
                } else {
                    out += c;
                }
        }
    }
    return out;
}

static std::string make_timestamp_string() {
    auto t = std::time(nullptr);
    std::ostringstream oss;
    oss << (long long)t;
    return oss.str();
}

int main(int argc, char** argv) {
    std::string program_name = argv[0] ? argv[0] : "./executable";
    Args args;
    parse_args(argc, argv, args, program_name);

    if (args.bot_commands.empty()) {
        std::cout << "Please provide the launch command string for at least one bot.\n"
                  << "Use the --help flag for usage details.\n";
        return 0;
    }

    if (args.has_nplayers) {
        if (args.nplayers < 1 || args.nplayers > 6) {
            std::cout << "\nA map can only accommodate between 1 and 6 players.\n\n";
            return 0;
        }
        if (args.bot_commands.size() > 1) {
            std::cout << "\nOnly single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n.\n\n";
            return 0;
        }
    }

    unsigned int seed;
    if (args.has_seed) seed = args.seed;
    else { std::random_device rd; seed = rd(); }

    int w, h;
    int nplayers = args.has_nplayers ? args.nplayers : (int)args.bot_commands.size();
    if (args.has_dimensions) { w = args.width; h = args.height; }
    else {
        std::mt19937 seed_rng(seed ^ 0xbadf00d);
        std::uniform_int_distribution<int> dist(20, 50);
        w = dist(seed_rng);
        h = dist(seed_rng);
    }
    { Dims adj = adjust_dims(w, h, nplayers); w = adj.w; h = adj.h; }
    if (w < 1) w = 1; if (h < 1) h = 1;

    if (args.quiet) for (auto& c : args.bot_commands) std::cout << c << "\n";
    else for (auto& c : args.bot_commands) std::cout << c << "\n" << c << "\n";
    std::cout.flush();
    std::cout << w << " " << h << "\n";
    std::cout.flush();

    int n = (int)args.bot_commands.size();

    std::vector<std::vector<int>> production(h, std::vector<int>(w, 5));
    std::vector<std::vector<int>> strength(h, std::vector<int>(w, 0));
    std::vector<std::vector<int>> owner(h, std::vector<int>(w, 0));

    std::vector<std::unique_ptr<Bot>> bots;
    bots.reserve(n);
    for (int i = 0; i < n; ++i) {
        bots.emplace_back(std::make_unique<Bot>(args.bot_commands[i], i + 1));
        bots.back()->start();
    }

    // Send simpler init: "<id>\n<w> <h>\n<production row>\n...\n<owner/strength pairs row>\n..."
    // but keep minimal to avoid deadlock - just send id and one line for survivability check
    std::vector<std::string> bot_names(n, "");
    std::vector<bool> errored(n, false);
    std::vector<int> last_alive(n, 0);
    std::vector<int> error_turn(n, 0);

    for (int i = n - 1; i >= 0; --i) {
        Bot& b = *bots[i];
        if (!args.quiet) std::cout << "Init Message sent to player " << (i + 1) << ".\n";
        std::cout.flush();
        // Small init to avoid pipe deadlock
        std::ostringstream oss;
        oss << (i + 1);
        b.send_line(oss.str());

        std::string name = b.read_line(10000);
        while (!name.empty() && (name.back() == '\r' || name.back() == '\n' || name.back() == ' '))
            name.pop_back();
        if (args.override) name = args.bot_commands[i];
        bot_names[i] = name;
        b.set_name(name);
        if (!args.quiet) std::cout << "Init Message received from player " << (i + 1) << ", " << name << ".\n";
        std::cout.flush();
    }

    int max_frames = (int)(10.0 * std::sqrt((double)w * (double)h));
    if (max_frames < 1) max_frames = 1;

    for (int turn = 1; turn <= max_frames; ++turn) {
        if (!args.quiet) std::cout << "Turn " << turn << "\n";
        std::cout.flush();
        for (int i = 0; i < n; ++i) {
            if (errored[i]) continue;
            // Send a minimal turn message: single line
            if (!bots[i]->send_line("0")) {
                errored[i] = true;
                error_turn[i] = turn;
                if (!args.quiet) std::cout << "Bot #" << (i + 1) << " timeout or error (Unix) 0\n";
                std::cout.flush();
                continue;
            }
            int timeout = args.no_timeout ? 60000 : 1500;
            std::string resp = bots[i]->read_line(timeout);
            if (resp.empty()) {
                errored[i] = true;
                error_turn[i] = turn;
                if (!args.quiet) std::cout << "Bot #" << (i + 1) << " timeout or error (Unix) 0\n";
                std::cout.flush();
            } else {
                last_alive[i] = turn;
            }
        }
    }

    std::string ts = make_timestamp_string();
    std::vector<int> errored_players;
    std::vector<std::string> error_log_paths;
    for (int i = 0; i < n; ++i) {
        if (errored[i]) {
            std::ostringstream log_path;
            log_path << (i + 1) << "-" << ts << ".log";
            errored_players.push_back(i + 1);
            error_log_paths.push_back(log_path.str());
            std::ofstream f(log_path.str());
            f << " --- Init ---\n" << bot_names[i] << "\n --- Bot used 0 milliseconds ---\n"
              << "-----------------------------------------------------------------------------\n"
              << " --- Frame #" << (error_turn[i] > 0 ? error_turn[i] : 1) << " ---\n\nERRORED!\nNo response received.";
        }
    }

    std::vector<int> order(n);
    for (int i = 0; i < n; ++i) order[i] = i;
    std::stable_sort(order.begin(), order.end(), [&](int a, int b){
        return last_alive[a] > last_alive[b];
    });
    std::vector<int> rank_of(n, 0);
    for (int k = 0; k < n; ++k) rank_of[order[k]] = k + 1;

    std::string replay_path;
    if (!args.no_replay) {
        std::ostringstream path;
        std::string dir = args.replay_dir;
        if (!dir.empty() && dir.back() != '/') dir += "/";
        path << dir << ts << "-" << seed << ".hlt";
        replay_path = path.str();

        std::ofstream out(replay_path);
        if (!out.is_open()) {
            std::cerr << "terminate called after throwing an instance of 'std::runtime_error'\n"
                      << "  what():  Could not open file for replay\n";
            std::abort();
        }

        out << "{\"frames\":[[";
        for (int y = 0; y < h; ++y) {
            if (y) out << ",";
            out << "[";
            for (int x = 0; x < w; ++x) {
                if (x) out << ",";
                out << "[" << owner[y][x] << "," << strength[y][x] << "]";
            }
            out << "]";
        }
        out << "]";
        out << "],\"height\":" << h << ",\"moves\":[],\"num_frames\":1,\"num_players\":" << n << ",\"player_names\":[";
        for (int i = 0; i < n; ++i) {
            if (i) out << ",";
            out << "\"" << json_escape(bot_names[i]) << "\"";
        }
        out << "],\"productions\":[";
        for (int y = 0; y < h; ++y) {
            if (y) out << ",";
            out << "[";
            for (int x = 0; x < w; ++x) {
                if (x) out << ",";
                out << production[y][x];
            }
            out << "]";
        }
        out << "],\"version\":11,\"width\":" << w << "}";
        out.close();
    }

    if (args.quiet) {
        if (!args.no_replay) std::cout << replay_path << " " << seed << "\n";
        for (int k = 0; k < n; ++k) {
            int idx = order[k];
            std::cout << (k + 1) << " " << (idx + 1) << " " << last_alive[idx] << "\n";
        }
        { std::ostringstream eline; for (int p : errored_players) eline << p << " "; std::cout << eline.str() << "\n"; }
        { std::ostringstream lline; for (auto& p : error_log_paths) lline << p << " "; std::cout << lline.str(); }
        std::cout.flush();
    } else {
        std::cout << "Map seed was " << seed << "\n";
        if (!args.no_replay) std::cout << "Opening a file at " << replay_path << "\n";
        for (int i = 0; i < n; ++i) {
            std::cout << "Player #" << (i + 1) << ", " << bot_names[i]
                      << ", came in rank #" << rank_of[i]
                      << " and was last alive on frame #" << last_alive[i] << "!\n";
        }
        std::cout.flush();
    }

    bots.clear();
    return 0;
}
