    Dims g = grid_layout(n);
    int nw = round_down_mult(w, g.w);
    int nh = round_down_mult(h, g.h);
    if (n <= 2 || n == 4) {
        if (nw % 2) nw--;
        if (nh % 2) nh--;
    }
    if (nw < 1) nw = 1;
    if (nh < 1) nh = 1;
    return {nw, nh};
}'''

new = '''static Dims adjust_dims(int w, int h, int n) {
    // Map generator requires dimensions divisible by a factor based on n
    int factor;
    switch (n) {
        case 1: factor = 1; break;
        case 2: factor = 2; break;
        case 3: factor = 3; break;
        case 4: factor = 2; break;
        case 5: factor = 5; break;
        case 6: factor = 6; break;
        default: factor = 1; break;
    }
    int nw = (w / factor) * factor;
    int nh = (h / factor) * factor;
    if (nw < factor) nw = factor;
    if (nh < factor) nh = factor;
    return {nw, nh};
}'''

content = content.replace(old, new)
with open('src/main.cpp', 'w') as f:
